(async () => {
  const f = (path, method = 'GET', data) => wp.apiFetch({ path, method, data }).catch((e) => ({ error: e.code || e.message, status: e.data && e.data.status }));
  const acc = await f('/wc/v3/payments/accounts');
  const onb = await f('/wc-admin/settings/payments/woopayments/onboarding', 'POST', {});
  const gen = await f('/wc/v3/settings/general');
  const pick = (id) => (gen.find ? (gen.find((s) => s.id === id) || {}).value : null);
  return {
    store_country: pick('woocommerce_default_country'), currency: pick('woocommerce_currency'),
    account: acc && !acc.error ? { country: acc.country, status: acc.status, test_mode: acc.test_mode, is_live: acc.is_live, default_currency: acc.store_currencies && acc.store_currencies.default, business_type: acc.business_type, payments_enabled: acc.payments_enabled, deposits: acc.deposits && acc.deposits.status, keys: Object.keys(acc).slice(0, 60) } : acc,
    onboarding_state: onb.state || onb,
  };
})()

(async () => {
  const f = (path, method = 'GET', data) => wp.apiFetch({ path, method, data }).catch((e) => ({ error: e.code || e.message, status: e.data && e.data.status }));
  const gen = await f('/wc/v3/settings/general');
  const pick = (id) => (gen.find ? (gen.find((s) => s.id === id) || {}).value : null);
  const acc = await f('/wc/v3/payments/accounts');
  const orders = await f('/wc/v3/orders?include=14,15&orderby=id&order=asc');
  const taxes = await f('/wc/v3/taxes');
  const onb = await f('/wc-admin/settings/payments/woopayments/onboarding', 'POST', {});
  return {
    store_country: pick('woocommerce_default_country'), currency: pick('woocommerce_currency'),
    account: acc && !acc.error ? { country: acc.country, status: acc.status, payments_enabled: acc.payments_enabled, default_currency: acc.store_currencies && acc.store_currencies.default, requirements: acc.requirements } : acc,
    onboarding_state: onb.state || onb,
    orders: Array.isArray(orders) ? orders.map((o) => [o.id, o.status, o.currency, o.total, o.total_tax]) : orders,
    taxes: Array.isArray(taxes) ? taxes.map((t) => [t.id, t.country, t.state, t.rate]) : taxes,
  };
})()

